// WP-G — festivais, prêmios, paradas, sociedades de gestão e leis (docs/db19.md §3.8, §3.9, §3.11, §5).
// Convenção do jogo: nome fictício + realRef real (mostrado só com nomes reais). Leis entram como marcos só de dados (Pack19.milestones):
// viram notícia/memória na data real; os efeitos de regra (cota de rádio, bloqueio etc.) são descritos em `mech` e ficam para a ligação
// por id (`law_*`) no WP-H/integrador, porque pacotes não podem trazer `appeal`/`onFire`.
// Notas de cidade (cidade real ausente em world.ts → mais próxima): Hellfest/Vieilles Charrues/Bourges → paris; Eurockéennes → strasbourg;
// Wacken → hamburg; Werchter/Pukkelpop/Dour → brussels; Pori → tampere; Carifesta (Georgetown) → port_of_spain; Split → zagreb;
// Jarocin/Opole → wroclaw; Cosquín (Córdoba) → buenos_aires; FIB Benicàssim/Benidorm → barcelona; Paléo (Nyon) → zurich;
// Byron Bay/Woodford → brisbane; Falls (Lorne)/Sunbury → melbourne; Avándaro (Valle de Bravo) → mexico_city; Vallenato (Valledupar) → cartagena.
import { l } from '../world';
import type { Festival, FestivalVibe } from '../catalog';
import type { AwardCategory, AwardDef, AwardKind, ChartDef, ChartScope } from '../content';
import type { Soc18 } from '../rights18';
import type { FamilyId } from '../world';
import type { Milestone } from '../../sim/sys/world4/milestones';
import type { Pack19 } from './types';

const t = (s: string) => { const [p, e] = s.split('~'); return l(p, e ?? p); };
const arr = (s: string) => (s ? s.split(',') : []);

// ===================================================================================== festivais (66)
/** F('nome fictício|equivalente real|cidade|início|fim(0)|mês 0–11|vibe|público|prestígio|reputação', 'famílias', 'gêneros', 'tipo pt~en', 'identidade pt~en') */
const F = (spec: string, focus: string, genres: string, kind: string, ident: string): Festival => {
  const [name, realRef, city, start, end, month, vibe, cap, prestige, rep] = spec.split('|');
  return {
    name, realRef, city, kind: t(kind), start: +start, end: +end || undefined, focus: arr(focus), prestige: +prestige, scouting: false,
    genres: arr(genres), reputation: +rep, capacity: +cap, month: +month, vibe: vibe as FestivalVibe, identity: t(ident),
  };
};

