const C = (id: string, pt: string, en: string, families?: string): AwardCategory => ({ id, name: l(pt, en), families: families ? (families.split(',') as FamilyId[]) : undefined });
/** A('id|nome fictício|equivalente real|tipo|mercado|início|fim(0)|mês|critérios|prestígio', [categorias], 'desc pt~en') */
const A = (spec: string, cats: AwardCategory[], desc: string): AwardDef => {
  const [id, name, realRef, kind, market, start, end, month, criteria, prestige] = spec.split('|');
  const d = t(desc);
  return { id, name, realRef, kind: kind as AwardKind, market: market as AwardDef['market'], start: +start, end: +end || undefined, month: +month, criteria: criteria.split(',') as AwardDef['criteria'], prestige: +prestige, categories: cats, desc: d };
};

