const Law = (id: string, year: number, month: number | undefined, title: string, text: string, mech: string, realRef: string, extra: Partial<Milestone> = {}): Milestone =>
  ({ id: 'law_' + id, year, month, realRef, title: t(title), text: t(text), mech: t(mech), ...extra });

